        "text": "[Medical Biochemistry Case v175-new-106-sutle-beslenme-sonrasi-yenidogan-sariligi] diagnosis.answerFeedback.optionComparison.Galaktoz-1-fosfat üridiltransferaz (GALT) eksikliği: GALT, galaktoz-1-fosfat ile UDP-glukozdan UDP-galaktoz ve glukoz-1-fosfat oluşmasını sağlar. Eksiklikte galaktoz-1-fosfat birikir; laktoz alımı sonrası kusma, kilo alamama, konjuge hiperbilirubinemi, hepatik disfonksiyon ve indirgen madde pozitifliği aynı biyokimyasal zincirle açıklanır."
