        "text": "[Medical Biochemistry Case v175-new-106-sutle-beslenme-sonrasi-yenidogan-sariligi] diagnosis.optionComparison.Galactose-1-phosphate uridyltransferase (GALT) eksikliği: GALT, galaktoz-1-fosfatı UDP-glukozla reaksiyona sokarak UDP-galaktoz ve glukoz-1-fosfat oluşturur. Eksiklikte galaktoz-1-fosfat birikir; sütle beslenme sonrası kusma, sarılık, hepatoselüler hasar, indirgen madde pozitifliği ve E. coli sepsis riski görülebilir."
